# Capture serial data to a file with robust framed mode and live status.
#
# Framed mode:
#   - Expects 11-byte frames: 4B PICstop + 4B tof + 1B ch + CR LF
#   - Initial flush: discard bytes for --flush-ms before alignment
#   - Align using CRLF-pair check: require two consecutive CRLF-terminated
#     11-byte slices before trusting the boundary
#   - Validate channel byte against --expect-channels (required for framed mode)
#   - Log discards: print to stderr; optionally write "# ..." lines to .log
#
# Raw mode:
#   - Dump all bytes verbatim to outfile with periodic status

import argparse
import sys
import time
from typing import Optional, Sequence

try:
    import serial  # pyserial
except ImportError:
    print("Missing dependency: pyserial. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

FRAME_LEN = 11
CR = 0x0D
LF = 0x0A


def human_rate(bytes_per_sec: float) -> str:
    if bytes_per_sec >= 1e6:
        return f"{bytes_per_sec/1e6:.2f} MB/s"
    if bytes_per_sec >= 1e3:
        return f"{bytes_per_sec/1e3:.2f} kB/s"
    return f"{bytes_per_sec:.0f} B/s"


def initial_flush(ser: serial.Serial, flush_ms: int) -> int:
    if flush_ms <= 0:
        return 0
    to_s = flush_ms / 1000.0
    deadline = time.time() + to_s
    flushed = 0
    # Set non-blocking small timeout during flush
    old_timeout = ser.timeout
    ser.timeout = 0.02
    try:
        while time.time() < deadline:
            chunk = ser.read(8192)
            if chunk:
                flushed += len(chunk)
    finally:
        ser.timeout = old_timeout
    return flushed


def capture_raw(ser: serial.Serial, out_f, status_interval: float):
    bytes_total = 0
    t0 = time.time()
    t_last = t0
    announced = False

    print("Status: starting raw capture (no framing). Waiting for data...", file=sys.stderr)

    try:
        while True:
            data = ser.read(8192)
            if data:
                out_f.write(data)
                bytes_total += len(data)
                if not announced:
                    print("Status: receiving data...", file=sys.stderr)
                    announced = True

            now = time.time()
            if now - t_last >= status_interval:
                elapsed = now - t0
                rate = bytes_total / elapsed if elapsed > 0 else 0.0
                print(
                    f"Raw: bytes={bytes_total} rate={human_rate(rate)} elapsed={elapsed:.1f}s",
                    file=sys.stderr,
                )
                t_last = now
                out_f.flush()
    except KeyboardInterrupt:
        pass
    finally:
        elapsed = max(1e-6, time.time() - t0)
        rate = bytes_total / elapsed
        print(
            f"\nStopped. Raw summary: bytes={bytes_total} avg={human_rate(rate)} duration={elapsed:.1f}s",
            file=sys.stderr,
        )


def capture_framed(
    ser: serial.Serial,
    out_f,
    status_interval: float,
    expect_channels: bytes,
    flush_ms: int,
    drop_logger: Optional[object],
):
    """
    Robust framed capture for 11-byte frames ending with CRLF.
    - Initial flush for flush_ms milliseconds
    - CRLF-pair alignment before trusting boundary
    - Channel byte (frame[8]) must be in expect_channels
    - Discarded segments reported to stderr, optionally "# ..." to drop_logger
    """
    if not expect_channels:
        print("Error: --expect-channels is required in --framed mode", file=sys.stderr)
        sys.exit(2)

    crlf = bytes([CR, LF])
    buf = bytearray()
    frames = 0
    drops = 0
    bytes_total = 0
    t0 = time.time()
    t_last = t0
    announced = False
    aligned = False

    # Initial flush
    flushed = initial_flush(ser, flush_ms)
    if flushed > 0:
        print(f"Status: initial flush discarded {flushed} bytes", file=sys.stderr)
        if drop_logger:
            drop_logger.write(f"# initial_flush {flushed} bytes discarded\n")

    print(
        "Status: starting framed capture (11B frames ending with CRLF). Waiting for data...",
        file=sys.stderr,
    )

    def log_drop(msg: str):
        nonlocal drops
        drops += 1
        print(f"[drop] {msg}", file=sys.stderr)
        if drop_logger:
            try:
                drop_logger.write(f"# {msg}\n")
                drop_logger.flush()
            except Exception:
                pass

    def try_align(buffer: bytearray) -> int:
        """
        Search for two consecutive 11B frames ending with CRLF.
        Returns the index after the first CRLF if alignment is found,
        or -1 if not found yet.
        """
        search_from = 0
        n = len(buffer)
        while True:
            j = buffer.find(crlf, search_from)
            if j < 0:
                return -1
            # Candidate first frame: [j-9 .. j+2)
            start1 = j - (FRAME_LEN - 2)
            end1 = j + 2
            start2 = end1
            end2 = start2 + FRAME_LEN
            if start1 >= 0 and end2 <= n:
                if buffer[end2 - 2 : end2] == crlf:
                    ch1 = buffer[start1 + 8]
                    ch2 = buffer[start2 + 8]
                    if (ch1 in expect_channels) and (ch2 in expect_channels):
                        return end1  # aligned after first CRLF
            search_from = j + 2

    try:
        while True:
            chunk = ser.read(4096)
            if chunk:
                buf.extend(chunk)
                if not announced:
                    print("Status: receiving data...", file=sys.stderr)
                    announced = True

            # Establish alignment if needed
            if not aligned:
                cut = try_align(buf)
                if cut is not None and cut >= 0:
                    # Drop everything up to and including first CRLF
                    if cut > 0:
                        log_drop(f"resync: discard {cut} bytes before alignment")
                        del buf[:cut]
                    aligned = True

            # Process frames when aligned
            while aligned and len(buf) >= FRAME_LEN:
                frame = buf[:FRAME_LEN]
                if frame[-2] != CR or frame[-1] != LF:
                    # Lost alignment: discard up to next CRLF and try to re-align
                    discard = len(buf)
                    tail_keep = min(len(buf), 2 * FRAME_LEN)
                    tail = bytes(buf[-tail_keep:])
                    buf.clear()
                    buf.extend(tail)
                    aligned = False
                    log_drop(f"misalign: discarded {discard - tail_keep} bytes, kept tail {tail_keep}")
                    break

                ch = frame[8]
                if ch not in expect_channels:
                    # Bad channel byte: drop this 11B and re-align using pair rule
                    del buf[:FRAME_LEN]
                    log_drop(f"bad channel 0x{ch:02X} at current frame; forcing re-align")
                    aligned = False
                    break

                # OK frame: write and advance
                out_f.write(frame)
                frames += 1
                bytes_total += FRAME_LEN
                del buf[:FRAME_LEN]

            now = time.time()
            if now - t_last >= status_interval:
                elapsed = now - t0
                rate = bytes_total / elapsed if elapsed > 0 else 0.0
                print(
                    f"Framed: frames={frames} drops={drops} bytes={bytes_total} "
                    f"rate={human_rate(rate)} buffered={len(buf)} aligned={aligned} elapsed={elapsed:.1f}s",
                    file=sys.stderr,
                )
                t_last = now
                out_f.flush()
    except KeyboardInterrupt:
        pass
    finally:
        elapsed = max(1e-6, time.time() - t0)
        rate = bytes_total / elapsed
        print(
            f"\nStopped. Framed summary: frames={frames} drops={drops} bytes={bytes_total} "
            f"avg={human_rate(rate)} duration={elapsed:.1f}s",
            file=sys.stderr,
        )


def main():
    p = argparse.ArgumentParser(description="Capture serial data to a file with live status.")
    p.add_argument("--port", required=True, help="Serial port (e.g., COM3 or /dev/ttyUSB0)")
    p.add_argument("--baud", type=int, required=True, help="Baud rate (e.g., 115200, 2000000)")
    p.add_argument("--outfile", required=True, help="Output file path")
    p.add_argument("--timeout", type=float, default=0.5, help="Serial read timeout (s)")
    p.add_argument(
        "--framed",
        action="store_true",
        help="Expect 11B frames ending with CRLF; write only whole frames with robust resync.",
    )
    p.add_argument(
        "--expect-channels",
        nargs="+",
        help="Required channel bytes for framed mode (e.g., A B or 0 1).",
    )
    p.add_argument(
        "--flush-ms",
        type=int,
        default=150,
        help="Initial flush duration in milliseconds before aligning (default 150 ms).",
    )
    p.add_argument("--status-interval", type=float, default=2.0, help="Status print interval (s)")
    p.add_argument(
        "--log-drops",
        action="store_true",
        help="Write human-readable '# ...' lines about discards to <outfile>.log",
    )
    args = p.parse_args()

    try:
        ser = serial.Serial(
            port=args.port,
            baudrate=args.baud,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=args.timeout,
        )
        # Optional: ensure DTR/RTS don't reset some boards unexpectedly
        try:
            ser.dtr = True
            ser.rts = False
        except Exception:
            pass
    except Exception as e:
        print(f"Failed to open serial port: {e}", file=sys.stderr)
        sys.exit(1)

    mode = "framed" if args.framed else "raw"
    print(f"Opening {args.port} @ {args.baud} baud, mode={mode}. Writing to {args.outfile}", file=sys.stderr)

    drop_logger = None
    if args.log_drops:
        try:
            drop_logger = open(args.outfile + ".log", "a", encoding="utf-8", newline="\n")
        except Exception as e:
            print(f"Warning: could not open drop log: {e}", file=sys.stderr)

    try:
        with open(args.outfile, "ab", buffering=0) as f:
            if args.framed:
                # Convert expect-channels strings to raw bytes
                if not args.expect_channels:
                    print("Error: --expect-channels is required for --framed mode.", file=sys.stderr)
                    sys.exit(2)
                # Accept both single ASCII characters and decimal byte codes
                ch_bytes = bytearray()
                for s in args.expect_channels:
                    if len(s) == 1:
                        ch_bytes.append(ord(s))
                    else:
                        # try int value
                        try:
                            val = int(s, 0)
                            if 0 <= val <= 255:
                                ch_bytes.append(val)
                            else:
                                raise ValueError
                        except Exception:
                            print(f"Error: invalid channel specifier '{s}'. Use 'A' 'B' or 0x41 0x42 etc.", file=sys.stderr)
                            sys.exit(2)

                capture_framed(
                    ser,
                    f,
                    status_interval=args.status_interval,
                    expect_channels=bytes(ch_bytes),
                    flush_ms=args.flush_ms,
                    drop_logger=drop_logger,
                )
            else:
                capture_raw(ser, f, status_interval=args.status_interval)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        if drop_logger:
            try:
                drop_logger.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()
